/* CS Fundamentals: an 8-bit adder you can click, and a fetch–decode–execute stepper (L52).
 *
 *   <div class="cpuviz" data-src="cpu-1"></div>
 *   <script type="application/json" id="cpu-1">{ ...spec... }</script>
 *   <script src="../assets/cpuviz.js"></script>
 *
 * Adder spec: { "kind": "adder", "a": 200, "b": 100 }
 *   Click any bit of A or B. Each column is a full adder: sum = a xor b xor carry-in,
 *   carry-out = majority(a, b, carry-in). "Subtract" feeds not B and a carry-in of 1 (two's complement).
 *
 * CPU spec (generated by driving the real Toy.Cpu, see .build/l52/viz/CpuTrace.java):
 *   { "kind": "cpu",
 *     "code": [ { "a": 0, "b": [16, 0], "asm": "LDI R0, 00" }, ... ],
 *     "dataAddr": [128, 129], "dataLabel": ["n", "answer"],
 *     "init": { "reg": [0,0,0,0], "data": [3, 0], "pc": 0 },
 *     "steps": [ { "phase": "fetch"|"decode"|"execute", "at": 0, "ir": [16, 0], "fields": "0001 00 00",
 *                  "reg": [...], "data": [...], "pc": 2, "note": "HTML ok" }, ... ] }
 */
(function () {
  const css = `
  .cpuviz { border: 1px solid var(--rule); border-radius: 8px; padding: .8rem; margin: 0 0 1.4rem; max-width: 40rem; outline: none; }
  .cpuviz:focus-visible { border-color: var(--accent); }
  .cz-ctl { display: flex; align-items: center; gap: .5rem; flex-wrap: wrap; margin-top: .4rem; }
  .cz-ctl button, .cz-bits button.cz-op { font: inherit; font-size: .82rem; color: var(--ink); background: var(--surface); border: 1px solid var(--rule); border-radius: 999px; padding: .2rem .8rem; cursor: pointer; }
  .cz-ctl button:disabled { opacity: .4; cursor: default; }
  .cz-count { font-family: var(--mono); font-size: .72rem; color: var(--ink-soft); }
  .cz-note { font-size: .9rem; min-height: 2.6rem; margin: .6rem 0 .4rem; padding: .45rem .7rem; background: var(--surface); border-radius: 5px; }
  /* adder */
  .cz-add { display: grid; grid-template-columns: 3.3rem repeat(8, minmax(1.25rem, 2.2rem)); gap: .25rem .2rem; align-items: center; font-family: var(--mono); font-size: .85rem; overflow-x: auto; }
  .cz-add .cz-lab { font-size: .66rem; letter-spacing: .06em; color: var(--ink-soft); }
  .cz-add .cz-lab i { display: block; font-style: normal; font-size: .72rem; letter-spacing: 0; color: var(--ink); }
  .cz-add button.cz-bit { font: inherit; font-weight: 600; padding: .25rem 0; border-radius: 4px; border: 1px solid var(--rule); background: var(--bg); color: var(--ink); cursor: pointer; }
  .cz-add button.cz-bit.cz-one { background: color-mix(in srgb, var(--kotlin) 18%, var(--bg)); border-color: var(--kotlin); color: var(--kotlin); }
  .cz-add span.cz-cell { text-align: center; padding: .25rem 0; border-radius: 4px; }
  .cz-add span.cz-carry { font-size: .72rem; color: var(--java); }
  .cz-add span.cz-carry.cz-one { font-weight: 700; }
  .cz-add span.cz-sum { border: 1px solid var(--ok); color: var(--ok); font-weight: 700; }
  .cz-add span.cz-head { font-size: .62rem; color: var(--ink-soft); text-align: center; }
  .cz-add .cz-rule { grid-column: 1 / -1; border-top: 1px solid var(--rule); }
  .cz-flags { display: flex; gap: 1rem; flex-wrap: wrap; font-family: var(--mono); font-size: .8rem; margin-top: .55rem; }
  .cz-flags b { color: var(--accent); }
  .cz-flags label { display: inline-flex; gap: .35rem; align-items: center; cursor: pointer; }
  /* cpu */
  .cz-cpu { display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr); gap: .8rem; }
  @media (max-width: 34rem) { .cz-cpu { grid-template-columns: 1fr; } }
  .cz-code { border-collapse: collapse; font-family: var(--mono); font-size: .76rem; width: 100%; }
  .cz-code td { padding: .12rem .3rem; border-bottom: 1px solid var(--rule); white-space: nowrap; }
  .cz-code td.cz-addr { color: var(--ink-soft); }
  .cz-code td.cz-bytes { color: var(--ink-soft); }
  .cz-code tr.cz-now td { background: color-mix(in srgb, var(--accent) 18%, var(--bg)); color: var(--ink); font-weight: 600; }
  .cz-code tr.cz-next td.cz-addr { color: var(--kotlin); font-weight: 700; }
  .cz-regs { display: grid; grid-template-columns: auto 1fr; gap: .25rem .6rem; font-family: var(--mono); font-size: .8rem; align-content: start; }
  .cz-regs b { font-size: .66rem; letter-spacing: .06em; color: var(--ink-soft); align-self: center; }
  .cz-regs span { padding: .1rem .4rem; border: 1px solid var(--rule); border-radius: 4px; }
  .cz-regs span.cz-chg { border-color: var(--accent); color: var(--accent); font-weight: 700; }
  .cz-regs span.cz-pc { border-color: var(--kotlin); color: var(--kotlin); }
  .cz-phase { display: flex; gap: .35rem; margin-bottom: .55rem; flex-wrap: wrap; }
  .cz-phase span { font-family: var(--mono); font-size: .66rem; letter-spacing: .08em; padding: .15rem .55rem; border-radius: 999px; border: 1px solid var(--rule); color: var(--ink-soft); }
  .cz-phase span.cz-on { border-color: var(--accent); background: var(--accent); color: var(--bg); font-weight: 700; }
  @media print { .cz-ctl { display: none; } }`;
  const style = document.createElement("style");
  style.textContent = css;
  document.head.appendChild(style);

  const hex = (x) => x.toString(16).toUpperCase().padStart(2, "0");

  function adder(root, spec) {
    let a = spec.a, b = spec.b, subtract = false;
    root.innerHTML = `<div class="cz-add"></div><div class="cz-flags"></div>`;
    const grid = root.querySelector(".cz-add"), flags = root.querySelector(".cz-flags");
    function draw() {
      const bIn = subtract ? (~b & 0xff) : b;
      let carry = subtract ? 1 : 0, sum = 0;
      const carries = [];                    // carry INTO each column, bit 0 first
      for (let i = 0; i < 8; i++) {
        carries.push(carry);
        const x = (a >> i) & 1, y = (bIn >> i) & 1;
        sum |= (x ^ y ^ carry) << i;
        carry = (x & y) | (x & carry) | (y & carry);
      }
      const col = (i) => 7 - i;              // draw bit 7 on the left
      let h = `<span class="cz-lab">BIT</span>` + [...Array(8)].map((_, k) => `<span class="cz-head">${col(k)}</span>`).join("");
      h += `<span class="cz-lab">CARRY</span>` + [...Array(8)].map((_, k) => {
        const c = carries[col(k)];
        return `<span class="cz-cell cz-carry${c ? " cz-one" : ""}">${c}</span>`;
      }).join("");
      h += `<span class="cz-lab">A<i>${a}</i></span>` + [...Array(8)].map((_, k) => {
        const v = (a >> col(k)) & 1;
        return `<button class="cz-bit${v ? " cz-one" : ""}" data-w="a" data-i="${col(k)}" aria-label="A bit ${col(k)}">${v}</button>`;
      }).join("");
      h += `<span class="cz-lab">${subtract ? "NOT B" : "B"}<i>${bIn}</i></span>` + [...Array(8)].map((_, k) => {
        const v = (bIn >> col(k)) & 1;
        return `<button class="cz-bit${v ? " cz-one" : ""}" data-w="b" data-i="${col(k)}" aria-label="B bit ${col(k)}">${v}</button>`;
      }).join("");
      h += `<div class="cz-rule"></div>`;
      h += `<span class="cz-lab">SUM<i>${sum}</i></span>` + [...Array(8)].map((_, k) => `<span class="cz-cell cz-sum">${(sum >> col(k)) & 1}</span>`).join("");
      grid.innerHTML = h;
      const signed = sum >= 128 ? sum - 256 : sum;
      const exact = subtract ? a - b : a + b;
      flags.innerHTML = `<span>carry out: <b>${carry}</b></span><span>unsigned: <b>${sum}</b></span><span>signed byte: <b>${signed}</b></span>` +
        `<span>exact ${subtract ? "A − B = " + a + " − " + b : "A + B"} = ${exact}</span>` +
        `<label><input type="checkbox" class="cz-sub"${subtract ? " checked" : ""}> subtract (A + not B + 1)</label>`;
    }
    root.addEventListener("click", (e) => {
      const btn = e.target.closest("button.cz-bit");
      if (!btn) return;
      const bit = 1 << Number(btn.dataset.i);
      if (btn.dataset.w === "a") a ^= bit; else b ^= bit;
      draw();
    });
    root.addEventListener("change", (e) => { if (e.target.classList.contains("cz-sub")) { subtract = e.target.checked; draw(); } });
    draw();
  }

  function cpu(root, spec) {
    let step = 0, timer = null;
    const rows = spec.code.map((c) =>
      `<tr data-a="${c.a}"><td class="cz-addr">${hex(c.a)}</td><td class="cz-bytes">${hex(c.b[0])} ${hex(c.b[1])}</td><td>${c.asm}</td></tr>`).join("");
    root.innerHTML = `<div class="cz-phase"><span data-p="fetch">FETCH</span><span data-p="decode">DECODE</span><span data-p="execute">EXECUTE</span></div>
      <div class="cz-cpu"><table class="cz-code" aria-label="program in memory">${rows}</table><div class="cz-regs"></div></div>
      <div class="cz-note" aria-live="polite"></div>
      <div class="cz-ctl"><button data-act="prev">◀ Back</button><button data-act="next">Step ▶</button>
      <button data-act="play">Play</button><button data-act="reset">Reset</button><span class="cz-count"></span></div>`;
    const n = spec.steps.length;
    const at = (k) => (k === 0 ? spec.init : spec.steps[k - 1]);
    function draw() {
      const st = at(step), prev = step > 0 ? at(step - 1) : st;
      root.querySelectorAll(".cz-phase span").forEach((s) => s.classList.toggle("cz-on", step > 0 && s.dataset.p === st.phase));
      root.querySelectorAll(".cz-code tr").forEach((tr) => {
        const a = Number(tr.dataset.a);
        tr.classList.toggle("cz-now", step > 0 && a === st.at);
        tr.classList.toggle("cz-next", a === st.pc);
      });
      const chg = (x, y) => (step > 0 && x !== y ? " cz-chg" : "");
      let h = `<b>PC</b><span class="cz-pc${chg(st.pc, prev.pc)}">${hex(st.pc)}</span>`;
      h += `<b>IR</b><span>${step > 0 ? hex(st.ir[0]) + " " + hex(st.ir[1]) : "—"}</span>`;
      h += `<b>OP RD RS</b><span>${step > 0 && st.phase !== "fetch" ? st.fields : "—"}</span>`;
      st.reg.forEach((v, i) => { h += `<b>R${i}</b><span class="${chg(v, prev.reg[i]).trim()}">${hex(v)}</span>`; });
      spec.dataAddr.forEach((addr, i) => {
        h += `<b>[${hex(addr)}]</b><span class="${chg(st.data[i], prev.data[i]).trim()}">${hex(st.data[i])} <em style="color:var(--ink-soft);font-style:normal">${spec.dataLabel[i]}</em></span>`;
      });
      root.querySelector(".cz-regs").innerHTML = h;
      root.querySelector(".cz-note").innerHTML = step > 0 ? st.note
        : "The program and its data share one memory. Press <b>Step</b> (or →) to watch the CPU fetch, decode and execute one instruction at a time.";
      root.querySelector(".cz-count").textContent = `step ${step}/${n}`;
      root.querySelector('[data-act="prev"]').disabled = step === 0;
      root.querySelector('[data-act="next"]').disabled = step === n;
      root.querySelector('[data-act="play"]').textContent = timer ? "Pause" : "Play";
    }
    const stop = () => { clearInterval(timer); timer = null; };
    root.addEventListener("click", (e) => {
      const b = e.target.closest("button");
      if (!b) return;
      const act = b.dataset.act;
      if (act === "next") { stop(); step = Math.min(n, step + 1); }
      else if (act === "prev") { stop(); step = Math.max(0, step - 1); }
      else if (act === "reset") { stop(); step = 0; }
      else if (act === "play") {
        if (timer) stop();
        else {
          if (step === n) step = 0;
          timer = setInterval(() => { step = Math.min(n, step + 1); if (step === n) stop(); draw(); }, 650);
        }
      }
      draw();
    });
    root.addEventListener("keydown", (e) => {
      if (e.key === "ArrowRight") { stop(); step = Math.min(n, step + 1); draw(); e.preventDefault(); }
      if (e.key === "ArrowLeft") { stop(); step = Math.max(0, step - 1); draw(); e.preventDefault(); }
    });
    draw();
  }

  document.querySelectorAll(".cpuviz").forEach((root) => {
    const spec = JSON.parse(document.getElementById(root.dataset.src).textContent);
    root.tabIndex = 0;
    if (spec.kind === "adder") adder(root, spec); else cpu(root, spec);
  });
})();
